// TH14 v1.00b Stage 5 Boss spell: st05bs.ecl.txt::BossCard3 (819-865)
// + MBossCard3_at (1126-1218). Entry anchor (0,128); source timer T0 = card frame 120.
// Source type 30 -> TH14_ARROW; native 0..23 keep the same modern slot.
const TH14_ARROW: int = 848;

const SPELL_ID: int = 76;
const SPELL_TIME: int = 2100;
const OPENING_BUFFER: int = 120;
const TIME_LIMIT: int = 2724;

// MBossCard3_at EX chain (1135-1151): BOUNCE(15), ACCEL 0.5, color 2, repeated.
// Source arms BOUNCE once per colour/ACCEL step; the target re-arm keeps the last
// count (engine cap 3), and the whole chain runs from birth.
xformdef CARD3_ARROW {
    bounce_arm(15, 3);
    @1 add_speed(0.5fx);
    set_color(2);
    @1 add_speed(0.5fx);
    set_color(3);
    @1 add_speed(0.5fx);
    set_color(4);
    @1 add_speed(0.3fx);
    set_color(5);
    @1 add_speed(0.2fx);
    set_color(6);
}

// One etOn(0) of MBossCard3_at: fixed direction, absolute offset, speed 1.4.
sub card3_shoot(b: fx, spread: int) {
    var ra: int = rand(65536) - 32768;                  // %RANDF2, angle
    var a: angle = (-16384 + (ra * spread) / 32768) as angle;
    var rx: int = rand(65536) - 32768;                  // %RANDF2, offset x
    var ry: int = rand(32768);                          // %RANDF, offset y 0..1
    var x: fx = b + ((rx as fx) / 32768) * 16fx;
    var y: fx = $self_y + ((ry as fx) / 32768) * 32fx;
    // Birth ANIM keeps position -= 4*velocity at the initial speed 1.4.
    var c: fx = cos(a);
    var s: fx = sin(a);
    _ = fire(TH14_ARROW, 1, x - 5.6fx * c, y - 5.6fx * s, 1.4fx, a, CARD3_ARROW, none);
}

// diffI($A,10,20,22,22) outer count and the per-shot wait (E 4, else 2).
sub card3_burst(ac: int, w: int, spread: int) {
    for i in 0..ac {
        var b: fx = -192fx;
        for j in 0..3 {
            card3_shoot(b, spread);
            b = b + 40fx;
            wait(w);
        }
        b = 192fx;
        for j2 in 0..3 {
            card3_shoot(b, spread);
            b = b - 40fx;
            wait(w);
        }
    }
}

// moveRand(60,4,1.0) recipe; moveLimit(0,128,280,128) = x[-140,140], y[64,192].
sub card3_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var sp: fx = 0fx;
    if k < 60 { sp = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * sp;
    var ny: fx = $self_y + self_fx(1) * sp;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 64fx { ny = 64fx; }
    if ny > 192fx { ny = 192fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card3_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card3_step();
}

sub card3_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 96fx {
        if a < 0 { a = -a; }
    } else if $self_y > 160fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05 rad (nearest BAM boundaries).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card3_begin_angle(a as angle);
}

sub card3_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card3_step();
    }
}

// BossCard3 body from the 150-frame mark: first MBossCard3_at, then the
// wait(30)/moveRand(60,4,1.0)/wait(600) loop. The spell timer ends the task.
async sub card3_attack() {
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);   // movePosTime(60,4,0,144)
    wait(60);                                 // anmSelect, visual only
    wait(60);                                 // anmSelectedPlay, visual only
    wait(30);                                 // anmReset / diffI / F0
    var ac: int = 20;
    var w: int = 2;
    var spread: int = 1820;
    if global(GVAR_RANK) == RANK_EASY { ac = 10; w = 4; }
    if global(GVAR_RANK) == RANK_HARD { ac = 22; spread = 2731; }
    if global(GVAR_RANK) >= RANK_LUNATIC { ac = 22; spread = 3641; }
    loop {
        card3_burst(ac, w, spread);
        wait(30);
        card3_move_rand();
        card3_wait(600);
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);      // setHitbox(48,48) ordinary circle -> r=24
    set_hurtbox(24fx);     // setHurtbox(48,48)
    spell_begin(0, SPELL_ID, card3_attack, SPELL_TIME, 500000, 0, 2700);
    wait_spell();
    wait(TIME_LIMIT - OPENING_BUFFER - SPELL_TIME);
    loop { wait(1); }
}

async sub stage_control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 3000, 0, 0, 0, boss_main);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, stage_control);
    loop { wait(1); }
}
